-- Source: internal/apptown/wow/schema.sql
CREATE TABLE IF NOT EXISTS lib_workflows (
  id UUID PRIMARY KEY,
  name           TEXT NOT NULL UNIQUE,
  description    TEXT NOT NULL DEFAULT '',
  latest_version BIGINT NOT NULL DEFAULT 1,
  origin         TEXT NOT NULL DEFAULT '',
  updated_at     TIMESTAMPTZ NOT NULL
);
CREATE TABLE IF NOT EXISTS lib_workflow_versions (
  id UUID PRIMARY KEY,
  lib_id UUID NOT NULL REFERENCES lib_workflows(id) ON DELETE CASCADE,
  version    BIGINT NOT NULL,
  yaml       TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  -- Where it came from: the source it was published by (flokkit, the
  -- built-in source, or here, this AppTown) and who signed what came in
  -- ('' for here; "shipped with AppTown <version>, unsigned" for stock a
  -- release shipped; "shipped with AppTown before <build>, unsigned" for
  -- stock older than this record).
  source     TEXT NOT NULL CONSTRAINT lib_workflow_version_source CHECK (source <> ''),
  signer     TEXT NOT NULL,
  UNIQUE(lib_id, version)
);
CREATE TABLE IF NOT EXISTS packs (
  id UUID PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL DEFAULT '',
  spec_json   JSONB NOT NULL DEFAULT '{}'::jsonb,
  latest_version BIGINT NOT NULL DEFAULT 0,
  -- The version new projects get and projects are offered as the update;
  -- a person moves it (design/subsystems/ways-of-working-versions.md).
  recommended_version BIGINT NOT NULL DEFAULT 0,
  origin      TEXT NOT NULL DEFAULT '',
  enabled     BOOLEAN NOT NULL DEFAULT true,
  updated_at  TIMESTAMPTZ NOT NULL
);
-- A pack version (§1.2): immutable; cut whenever the pack's spec changes.
CREATE TABLE IF NOT EXISTS pack_versions (
  id UUID PRIMARY KEY,
  pack_id UUID NOT NULL REFERENCES packs(id) ON DELETE CASCADE,
  version    BIGINT NOT NULL,
  spec_json  JSONB NOT NULL,
  note       TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL,
  pins_json  JSONB NOT NULL DEFAULT '{}'::jsonb,   -- block name → exact version, pinned at publish (§1.2)
  -- What the author wrote; spec_json and pins_json are its pinned result.
  declaration_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- An optional name, and the version of this pack it was made from (0: none).
  name       TEXT NOT NULL DEFAULT '',
  based_on   BIGINT NOT NULL DEFAULT 0,
  -- Where it came from, as lib_workflow_versions says.
  source     TEXT NOT NULL CONSTRAINT pack_version_source CHECK (source <> ''),
  signer     TEXT NOT NULL,
  UNIQUE(pack_id, version)
);
CREATE TABLE IF NOT EXISTS policy_library (
  id UUID PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL DEFAULT '',
  rule        TEXT NOT NULL,
  config_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  origin      TEXT NOT NULL DEFAULT '',
  updated_at  TIMESTAMPTZ NOT NULL
);
CREATE TABLE IF NOT EXISTS guidance_blocks (
  id UUID PRIMARY KEY,
  name           TEXT NOT NULL UNIQUE,
  tags           TEXT NOT NULL DEFAULT '',
  latest_version BIGINT NOT NULL DEFAULT 1,
  origin         TEXT NOT NULL DEFAULT '',
  created_at     TIMESTAMPTZ NOT NULL,
  updated_at     TIMESTAMPTZ NOT NULL,
  tier           TEXT NOT NULL DEFAULT '',  -- '' | platform (rides on every repo-backed project)
  conflicts      TEXT NOT NULL DEFAULT ''   -- comma list of blocks this one contradicts
);
CREATE TABLE IF NOT EXISTS guidance_block_versions (
  id UUID PRIMARY KEY,
  block_id UUID NOT NULL REFERENCES guidance_blocks(id) ON DELETE CASCADE,
  version     BIGINT NOT NULL,
  body_md     TEXT NOT NULL,
  checks_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at  TIMESTAMPTZ NOT NULL,
  -- Where it came from, as lib_workflow_versions says.
  source      TEXT NOT NULL CONSTRAINT guidance_block_version_source CHECK (source <> ''),
  signer      TEXT NOT NULL,
  UNIQUE(block_id, version)
);
CREATE TABLE IF NOT EXISTS system_workflows (
  stock_name TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL
);

-- Immutable local classification evidence; revocation never removes its meaning.
CREATE TABLE IF NOT EXISTS routine_publication_classifications (
 id UUID PRIMARY KEY,
 publication_kind TEXT NOT NULL CHECK (publication_kind IN ('block','pack')),
 publication_id UUID NOT NULL,
 from_version BIGINT NOT NULL CHECK (from_version > 0),
 to_version BIGINT NOT NULL CHECK (to_version > from_version),
 digest TEXT NOT NULL CHECK (digest <> ''),
 issuer_id UUID NOT NULL,
 request_id UUID NOT NULL,
 created_at TIMESTAMPTZ NOT NULL,
 record_json JSONB NOT NULL,
 revocation_json JSONB NOT NULL DEFAULT 'null'::jsonb,
 UNIQUE(issuer_id,request_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS routine_publication_active_digest ON routine_publication_classifications(digest) WHERE revocation_json = 'null'::jsonb;

-- Source: internal/apptown/adoption/schema.sql
-- Which pack versions a project is on (§1.1): placed at migration from the
-- evidence (§7), moved by adoption afterwards. An observation at placement,
-- never a claim about history.
CREATE TABLE IF NOT EXISTS project_packs (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  pack_id UUID NOT NULL REFERENCES packs(id) ON DELETE CASCADE,
  version    BIGINT NOT NULL,
  reason     TEXT NOT NULL DEFAULT '',
  adopted_by TEXT NOT NULL DEFAULT '',
  -- The adopter's principal and way of acting (access.Actor); NULL for AppTown, or one not resolved to a person.
  adopted_by_principal UUID,
  adopted_by_via TEXT NOT NULL DEFAULT '',
  adopted_at TIMESTAMPTZ NOT NULL,
  UNIQUE(project_id, pack_id)
);
-- Adoption owns a project's current selection separately from its immutable
-- receipt history. A zero or unavailable revision remains observable without
-- manufacturing a receipt; current is never inferred from the newest history.
CREATE TABLE IF NOT EXISTS adoptions (
  project_id UUID PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  revision BIGINT NOT NULL DEFAULT 0,
  drift_note TEXT NOT NULL DEFAULT ''
);
-- An adoption revision (§1.1, §4.1): the exact way of working a project is
-- on, as an immutable receipt with a digest. adoptions.revision selects the
-- current one within its project; target revisions are independent history.
CREATE TABLE IF NOT EXISTS project_adoptions (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  revision     BIGINT NOT NULL,
  kind         TEXT NOT NULL,                 -- legacy-snapshot | edit | drift
  reason       TEXT NOT NULL DEFAULT '',
  digest       TEXT NOT NULL,
  created_by   TEXT NOT NULL DEFAULT '',
  -- The author's principal and way of acting (access.Actor); NULL for AppTown, or one not resolved to a person.
  created_by_principal UUID,
  created_by_via TEXT NOT NULL DEFAULT '',
  created_at   TIMESTAMPTZ NOT NULL,
  receipt_json JSONB NOT NULL,
  -- An uplift's target (kind target) belongs to one change: its change_id,
  -- with revision 0. Every other row is a revision of the project.
  change_id    UUID
);
CREATE UNIQUE INDEX IF NOT EXISTS project_adoptions_revision ON project_adoptions(project_id, revision) WHERE change_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS project_adoptions_target ON project_adoptions(project_id, change_id) WHERE change_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS policies (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  rule        TEXT NOT NULL,
  config_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  origin      TEXT NOT NULL DEFAULT '',
  created_at  TIMESTAMPTZ NOT NULL,
  UNIQUE(project_id, name)
);
CREATE TABLE IF NOT EXISTS guidance_imports (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  position   BIGINT NOT NULL,
  block_id UUID NOT NULL REFERENCES guidance_blocks(id) ON DELETE CASCADE,
  version    BIGINT NOT NULL,
  disabled   BOOLEAN NOT NULL DEFAULT false
);
-- Workflows as lanes (design/decisions/workflows-as-lanes.md): a project SELECTS
-- lanes from the library; system workflows are bound per instance.
CREATE TABLE IF NOT EXISTS project_lanes (
  project_id UUID NOT NULL,
  name       TEXT NOT NULL,
  enabled    BOOLEAN NOT NULL DEFAULT true,
  updated_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (project_id, name)
);
-- Opt-in pi extensions enabled per project (extensions.go): the blessed
-- baked extension set is off by default; a row here turns one on.
CREATE TABLE IF NOT EXISTS project_pi_extensions (
  project_id UUID NOT NULL,
  name       TEXT NOT NULL,
  PRIMARY KEY (project_id, name)
);

-- Source: internal/apptown/adrs/schema.sql
CREATE TABLE IF NOT EXISTS adrs (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  number        BIGINT NOT NULL,
  title         TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'draft',
  body_md       TEXT NOT NULL DEFAULT '',
  tags          TEXT NOT NULL DEFAULT '',
  supersedes_id UUID,
