  outcome_revision     BIGINT NOT NULL DEFAULT 0,
  cost_micros          BIGINT NOT NULL DEFAULT 0,
  updated_at           TIMESTAMPTZ NOT NULL
);
CREATE TABLE IF NOT EXISTS remediation_attempts (
  id UUID PRIMARY KEY,
  item_id UUID NOT NULL REFERENCES remediation_items(id) ON DELETE CASCADE,
  n           BIGINT NOT NULL,
  change_id UUID,
  run_id UUID,
  base_sha    TEXT NOT NULL DEFAULT '',
  outcome     TEXT NOT NULL DEFAULT '',
  cost_micros  BIGINT NOT NULL DEFAULT 0,
  reason      TEXT NOT NULL DEFAULT '',
  started_at  TIMESTAMPTZ NOT NULL,
  finished_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS remediations_number ON remediations(number);
-- The last number given to one of remediations: the next is one more, whatever was
-- deleted since, so a number never names a second record.
CREATE TABLE IF NOT EXISTS remediation_numbers (
  id   BOOLEAN PRIMARY KEY DEFAULT true CONSTRAINT remediation_numbers_one CHECK (id),
  last BIGINT NOT NULL
);

-- Source: internal/apptown/workflow/schema.sql
CREATE TABLE IF NOT EXISTS changes (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  -- The change's number within its project, for people: "egg-catch#12".
  -- Allocated in the creating transaction from project_numbers; never an
  -- identity (design/decisions/mergeable-forge-data.md).
  number       BIGINT NOT NULL,
  type         TEXT NOT NULL,
  title        TEXT NOT NULL,
  body         TEXT NOT NULL DEFAULT '',
  run_id UUID,
  state        TEXT NOT NULL DEFAULT 'in_progress',
  branch       TEXT NOT NULL DEFAULT '',
  base_sha     TEXT NOT NULL DEFAULT '',
  landed_sha   TEXT NOT NULL DEFAULT '', -- the commit its landing merged as; '' until it lands
  external_ref TEXT NOT NULL DEFAULT '',
  summary      TEXT NOT NULL DEFAULT '',
  provenance   TEXT NOT NULL DEFAULT '',
  title_ownership TEXT NOT NULL DEFAULT 'human' CONSTRAINT change_title_ownership CHECK(title_ownership IN ('human','awaiting_chat','generated')),
  created_at   TIMESTAMPTZ NOT NULL,
  closed_at    TIMESTAMPTZ,
  target_adoption_id UUID, -- an uplift's target revision (ways-of-working-versions.md §11)
  acceptance_json    JSONB NOT NULL DEFAULT '{}'::jsonb, -- what the change must prove, structurally
  expected_revision  BIGINT NOT NULL DEFAULT 0,        -- the revision the target was prepared from
  adopted_revision   BIGINT NOT NULL DEFAULT 0,        -- set when the landing moved the project
  target_candidate_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- Advances with every human edit of the title, body or external reference,
  -- so an edit started from an older reading is refused, not applied.
  edit_revision      BIGINT NOT NULL DEFAULT 0,
  -- Who opened the change: the actor of its change.created receipt, written
  -- with it, so a change read need not search the ledger. '' when unknown.
  opened_by          TEXT NOT NULL DEFAULT '',
  -- The opener's principal and how they acted (access.Actor); NULL and ''
  -- when the opener was not resolved to a person.
  opened_by_principal UUID,
  opened_by_via      TEXT NOT NULL DEFAULT '',
  -- Whether the change does what was asked, as the narrative writer read the
  -- request against the work, with the shortfall in words when it does not.
  -- Written with the summary; 'unknown' until a narrative says.
  request_met        TEXT NOT NULL DEFAULT 'unknown' CONSTRAINT change_request_met CHECK(request_met IN ('yes','partly','no','unknown')),
  request_gap        TEXT NOT NULL DEFAULT '',
  -- How a closed change was closed, when that is more than its state: the
  -- engine's nothing-to-change close (an abandoned change whose run found
  -- nothing to change) is 'nothing-to-change'; a change a later landing
  -- shipped is 'shipped-with'; one a record run (research, a
  -- specification) shipped with nothing to land is 'record'; '' otherwise.
  -- Only the engine writes it. Last, where migration 148 added it.
  closed_as          TEXT NOT NULL DEFAULT '' CONSTRAINT change_closed_as CHECK(closed_as IN ('','nothing-to-change','shipped-with','record')),
  UNIQUE(project_id, number)
);
-- The last number given to a change and to a run in each project. A
-- creating transaction takes the next under this row's lock, so numbers are
-- allocated in commit order within a project.
CREATE TABLE IF NOT EXISTS project_numbers (
  project_id UUID PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  changes    BIGINT NOT NULL DEFAULT 0,
  runs       BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS runs (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  number           BIGINT NOT NULL, -- within its project, as a change's

  workflow_name    TEXT NOT NULL,
  workflow_version BIGINT NOT NULL,
  kind             TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'running',
  current_stage    TEXT NOT NULL,
  definition_json  JSONB NOT NULL,
  change_id UUID,
  workflow_origin  TEXT NOT NULL DEFAULT '',
  parent_run_id UUID,
  parent_step_id UUID,
  parent_step_attempt BIGINT NOT NULL DEFAULT 0,
  inputs_json      JSONB NOT NULL DEFAULT '{}'::jsonb,
  retry_revision   BIGINT NOT NULL DEFAULT 0,
  base_sha         TEXT NOT NULL DEFAULT '',
  created_at       TIMESTAMPTZ NOT NULL,
  updated_at       TIMESTAMPTZ NOT NULL,
  adoption_id UUID, -- the adoption revision this run reads
  -- Who admitted this root run while holding change:land on its change, ''
  -- when nobody did. One of the two facts a merge or deploy may rest on
  -- (assent.go); the other is a person's approval recorded in the run.
  landing_authority TEXT NOT NULL DEFAULT '',
  -- The landing authority's principal and way of acting (access.Actor); NULL for none, an eval's authority, or one not resolved to a person.
  landing_authority_principal UUID,
  landing_authority_via TEXT NOT NULL DEFAULT '',
  UNIQUE(project_id, number)
);
-- Only new runs have a start record. Legacy runs retain their recovery rules.
CREATE TABLE IF NOT EXISTS run_starts (
  run_id UUID PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE,
  ready BOOLEAN NOT NULL DEFAULT false
);
-- The landing created from a particular accepted working run. Linking it in
-- the run-creation transaction makes retries after a crash reuse that run.
-- A send-back gets a new completion identity; old landing jobs cannot ship it.
CREATE TABLE IF NOT EXISTS workflow_continuations (
  source_run_id UUID PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE,
  run_id UUID NOT NULL UNIQUE REFERENCES runs(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS workflow_landings (
  work_run_id UUID PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE,
  landing_run_id UUID UNIQUE REFERENCES runs(id) ON DELETE CASCADE,
  acceptance_applied BOOLEAN NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS steps (
  attempt BIGINT NOT NULL DEFAULT 0,
  id UUID PRIMARY KEY,
  run_id UUID NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  stage           TEXT NOT NULL,
  name            TEXT NOT NULL,
  type            TEXT NOT NULL,
  config_json     JSONB NOT NULL DEFAULT '{}'::jsonb CONSTRAINT steps_config_object CHECK (jsonb_typeof(config_json)='object'),
  status          TEXT NOT NULL DEFAULT 'pending',
  evidence_json   JSONB NOT NULL DEFAULT '{}'::jsonb,
  override_by     TEXT NOT NULL DEFAULT '',
  override_by_principal UUID,
  override_by_via TEXT NOT NULL DEFAULT '',
  override_reason TEXT NOT NULL DEFAULT '',
  started_at      TIMESTAMPTZ,
  finished_at     TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS run_events (
  id UUID PRIMARY KEY,
  run_id UUID NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  at           TIMESTAMPTZ NOT NULL,
  kind         TEXT NOT NULL,
  payload_json JSONB NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE IF NOT EXISTS artifacts (
  id UUID PRIMARY KEY,
  run_id UUID NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL,
  name       TEXT NOT NULL DEFAULT '',
  ref        TEXT NOT NULL DEFAULT '',
  body       TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL,
  -- body_bytes holds a body that is not text (a file an agent produced,
  -- a log with raw bytes) faithfully; body is then empty. Never both.
  body_bytes BYTEA
);
-- A project's scheduled workflow: when it last fired and what that firing
-- did. Arming a schedule seen for the first time writes the same time as a
-- firing, so last_outcome says which it was: armed (never fired yet),
-- opened (last_change_id is the change it opened), skipped (its previous
-- run was still active), failed (its run could not be started), or unknown
-- (recorded before outcomes were kept, schema 144).
CREATE TABLE IF NOT EXISTS workflow_schedules (
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  workflow_name TEXT NOT NULL,
  last_fired_at TIMESTAMPTZ NOT NULL,
  last_outcome TEXT NOT NULL DEFAULT 'unknown',
  last_change_id UUID,
  PRIMARY KEY (project_id, workflow_name),
  CONSTRAINT workflow_schedule_outcome CHECK (last_outcome IN ('armed','opened','skipped','failed','unknown')
    AND (last_outcome = 'opened') = (last_change_id IS NOT NULL))
);
CREATE TABLE IF NOT EXISTS run_inference_owners (
  run_id UUID PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE,
  actor TEXT NOT NULL,
  -- The owner's principal and way of acting (access.Actor); NULL for AppTown, a run, or one not resolved to a person.
  actor_principal UUID,
  actor_via TEXT NOT NULL DEFAULT ''
);
-- An agent attempt's kept history: the digest of its session's transcript,
-- stored immutably under dataDir/transcripts, or why it was not kept. One row
-- per invocation of the attempt, so every stored file keeps its reference;
-- the attempt's history is its latest invocation's. The attempt's start
-- receipt names the session.
CREATE TABLE IF NOT EXISTS agent_transcripts (
  run_id UUID NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  step_id UUID NOT NULL REFERENCES steps(id) ON DELETE CASCADE,
  attempt BIGINT NOT NULL,
  session_id TEXT NOT NULL,
  invocation BIGINT NOT NULL,
  digest TEXT NOT NULL DEFAULT '',
  unavailable TEXT NOT NULL DEFAULT '',
  recorded_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (step_id, attempt, invocation),
  CONSTRAINT agent_transcript_tuple CHECK (attempt>0 AND invocation>0 AND session_id<>'' AND ((digest<>'') <> (unavailable<>'')))
);
CREATE INDEX IF NOT EXISTS agent_transcripts_digest ON agent_transcripts(digest) WHERE digest <> '';

-- Project summaries and run-scoped step reads must not rescan all history.
CREATE INDEX IF NOT EXISTS changes_project ON changes(project_id);
CREATE INDEX IF NOT EXISTS runs_project ON runs(project_id);
CREATE INDEX IF NOT EXISTS steps_run_stage ON steps(run_id, stage);

-- Dashboard active work is bounded by recency, independently of project totals.
CREATE INDEX IF NOT EXISTS runs_status_updated ON runs(status, updated_at DESC, id DESC);

-- Standing consent survives project/account deletion as immutable evidence.
CREATE TABLE IF NOT EXISTS standing_rules (id UUID PRIMARY KEY, current_revision BIGINT NOT NULL CHECK(current_revision > 0));
CREATE TABLE IF NOT EXISTS standing_rule_revisions (rule_id UUID NOT NULL REFERENCES standing_rules(id), revision BIGINT NOT NULL CHECK(revision > 0), enabled BOOLEAN NOT NULL, record_json JSONB NOT NULL, PRIMARY KEY(rule_id,revision));

-- Source: internal/apptown/deployment/schema.sql
CREATE TABLE IF NOT EXISTS releases (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  number       BIGINT NOT NULL,
  state        TEXT NOT NULL DEFAULT 'released',
  deployment  TEXT NOT NULL DEFAULT 'prod',
  external_ref TEXT NOT NULL DEFAULT '',
  approved_by  TEXT NOT NULL DEFAULT '',
  run_id UUID,
  created_at   TIMESTAMPTZ NOT NULL,
  released_at  TIMESTAMPTZ,
  notes        TEXT NOT NULL DEFAULT '',
  commit_sha   TEXT NOT NULL DEFAULT '',
  source_sha   TEXT NOT NULL DEFAULT '',
  bundle_id UUID, -- §2.8: what shipped
  deployment_id UUID, -- §2.8: where
  generation     BIGINT NOT NULL DEFAULT 0,   -- the deployment's generation this release is
  artifact_hash  TEXT NOT NULL DEFAULT '',    -- the rendered artifact's hash
  -- shipped: AppTown released it. observed-after-restore: after AppTown was
  -- restored, the provider was found running something else, recorded as
  -- what runs and never as something AppTown shipped (external_ref names it).
  origin TEXT NOT NULL DEFAULT 'shipped' CONSTRAINT release_origin CHECK (origin IN ('shipped', 'observed-after-restore')),
  UNIQUE(project_id, number)
);
CREATE TABLE IF NOT EXISTS release_changes (
  release_id UUID NOT NULL REFERENCES releases(id) ON DELETE CASCADE,
  change_id UUID NOT NULL REFERENCES changes(id) ON DELETE CASCADE,
  PRIMARY KEY (release_id, change_id)
);
CREATE TABLE IF NOT EXISTS release_events (
  id UUID PRIMARY KEY,
  release_id UUID NOT NULL REFERENCES releases(id) ON DELETE CASCADE,
  at         TIMESTAMPTZ NOT NULL,
  text       TEXT NOT NULL
);
-- A deployment (design/subsystems/deployment.md §2.3): identity, a kind, a binding
-- to a target, the target-specific handle the driver owns, the desired and
-- observed deployment generations, and the four attributes that carry the
-- nuance (§2.3a; protected is derived in Go). A preview row is named
-- preview-<change> so (project, name) stays the one key. host_port and
-- container are the built-in Docker host's handle, kept as columns because
-- the boot path reads them; other kinds keep theirs in handle_json.
CREATE TABLE IF NOT EXISTS deployments (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  -- The name the deployment carries on its host (apptown.deployment labels,
  -- boot proofs): its old integer for a deployment made before the identity
  -- cutover, kept because its containers carry it; '' for one made after,
  -- which uses its UUID.
  host_label TEXT NOT NULL DEFAULT '',
  host_port  BIGINT NOT NULL DEFAULT 0,
  container  TEXT NOT NULL DEFAULT '',
  release_run UUID,
  updated_at TIMESTAMPTZ NOT NULL,
  release_sha  TEXT NOT NULL DEFAULT '', -- the commit the serving release was built from
  image_digest TEXT NOT NULL DEFAULT '', -- the image id it actually runs (artifact identity)
  kind         TEXT NOT NULL DEFAULT 'standing',   -- standing | preview | restored-copy
  change_id UUID, -- previews only
  target_id UUID,
  handle_json  JSONB NOT NULL DEFAULT '{}'::jsonb,
  desired_generation  BIGINT NOT NULL DEFAULT 0,
  observed_generation BIGINT NOT NULL DEFAULT 0,
  readiness    TEXT NOT NULL DEFAULT 'reconciled', -- reconciled | reconciling | uncertain | failed
  feed         TEXT NOT NULL DEFAULT 'landing',    -- landing | promotion | schedule | manual
  audience     TEXT NOT NULL DEFAULT 'team',       -- team | organisation | partners | public
  data_class   TEXT NOT NULL DEFAULT 'synthetic',  -- synthetic | non-production | production
  url          TEXT NOT NULL DEFAULT '',
  -- A deployment started from a copy: the set its first release fills its
  -- data from, and when that was done (null until then).
  start_from_backup UUID,
  started_from_at   TIMESTAMPTZ,
  -- After AppTown was restored, an App Platform or Portainer deployment is
  -- not acted on until its provider says what it runs: unconfirmed until
  -- then, gone when the provider has no such app. A built-in deployment is
  -- filling until the rebuild that puts its data back has ended. '' otherwise.
  restore_check TEXT NOT NULL DEFAULT '' CONSTRAINT deployment_restore_check CHECK (restore_check IN ('', 'unconfirmed', 'gone', 'filling', 'not-filled')),
  display_label TEXT NOT NULL DEFAULT '',
  CONSTRAINT deployments_project_identity UNIQUE(project_id, id),
  UNIQUE(project_id, name)
);
CREATE UNIQUE INDEX IF NOT EXISTS deployments_host_key ON deployments ((right(id::text, 12)));
-- A target (design/subsystems/deployment.md §2.2): a reusable place AppTown can
-- deploy to, reached through one provider (an integration name, '' for
-- the built-in host). Absent by default except the built-in Docker host.
CREATE TABLE IF NOT EXISTS targets (
  id UUID PRIMARY KEY,
  name              TEXT NOT NULL UNIQUE,
  kind              TEXT NOT NULL,                 -- docker-host | portainer | do-app | ...
  provider          TEXT NOT NULL DEFAULT '',
  address_json      JSONB NOT NULL DEFAULT '{}'::jsonb,
  origin            TEXT NOT NULL DEFAULT 'attached', -- built-in | attached | provisioned
  capabilities_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  ingress_json      JSONB NOT NULL DEFAULT '{}'::jsonb,
  needs_mode        TEXT NOT NULL DEFAULT 'emulators', -- emulators | managed | register
  status            TEXT NOT NULL DEFAULT 'ready',
  created_at        TIMESTAMPTZ NOT NULL,
  updated_at        TIMESTAMPTZ NOT NULL,
  -- Advances when the capabilities, ingress or needs mode change, never with
  -- a status check, so an edit started from an older reading is refused
  -- without routine checks causing conflicts.
  settings_revision BIGINT NOT NULL DEFAULT 0,
  connection_id UUID REFERENCES integrations(id) ON DELETE RESTRICT,
  provider_scope_json JSONB,
  display_label TEXT NOT NULL DEFAULT ''
);
-- A release bundle (§2.8): the immutable thing that ships, committed once
-- by a landing's deploy step attempt.
CREATE TABLE IF NOT EXISTS release_bundles (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  contract_revision TEXT NOT NULL,                  -- the tree sha
  contract_hash     TEXT NOT NULL DEFAULT '',       -- sha256 of the contract bytes
  parts_json        JSONB NOT NULL DEFAULT '{}'::jsonb, -- part -> image id, or <registry>@sha256:<hex>
  init_json         JSONB NOT NULL DEFAULT '{}'::jsonb, -- init step -> image id, or <registry>@sha256:<hex>
  built_from_json   JSONB NOT NULL DEFAULT '{}'::jsonb, -- change, run, tree
  created_at        TIMESTAMPTZ NOT NULL,
  -- the target whose daemon the image IDs were read from; NULL for a
  -- digest bundle, and for a bundle that names no host
  target_id UUID,
  -- A digest bundle's repository, every image of it by digest there; ''
  -- for a bundle of daemon image IDs.
  registry          TEXT NOT NULL DEFAULT '',
  platform          TEXT NOT NULL DEFAULT '',             -- os/arch, a digest bundle's
  built_on_json     JSONB NOT NULL DEFAULT '{}'::jsonb,   -- where a digest bundle was built
  -- The deploy step attempt that committed the bundle; 0 for bundles
  -- committed before attempts were recorded.
  run_id UUID,
  step_id UUID,
  attempt           BIGINT NOT NULL DEFAULT 0,
  CONSTRAINT release_bundle_form CHECK (registry = '' OR (platform <> '' AND target_id IS NULL AND attempt > 0))
);
-- One bundle per deploy step attempt.
CREATE UNIQUE INDEX IF NOT EXISTS release_bundles_attempt ON release_bundles(step_id, attempt) WHERE attempt > 0;
-- One attempt to bring a deployment to a generation (§2.4): the
-- idempotency key makes a retry the same attempt.
CREATE TABLE IF NOT EXISTS deployment_attempts (
  id UUID PRIMARY KEY,
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,
  generation      BIGINT NOT NULL,
  idempotency_key TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'running',  -- running | uncertain | done | failed | superseded
  terminal        BOOLEAN NOT NULL DEFAULT false,
  observed_json   JSONB NOT NULL DEFAULT '{}'::jsonb,
  superseded_by UUID,
  started_at      TIMESTAMPTZ NOT NULL,
  finished_at     TIMESTAMPTZ,
  UNIQUE(deployment_id, idempotency_key)
);
-- Immutable, non-secret inputs required by deployment execution. Migration 62
-- converts old release-linked facts once; missing inputs remain unresolved.
CREATE TABLE IF NOT EXISTS deployment_attempt_inputs (
  attempt_id UUID PRIMARY KEY REFERENCES deployment_attempts(id) ON DELETE CASCADE,
  release_id UUID,
  release_run UUID,
  revision      TEXT NOT NULL DEFAULT '',
  image_digest  TEXT NOT NULL DEFAULT '',
  artifact_hash TEXT NOT NULL DEFAULT '',
  docker_source TEXT NOT NULL DEFAULT '',
  rebuild BOOLEAN NOT NULL DEFAULT false,
  bundle_id UUID,
  -- What the generation applied of the deployment's profile and
  -- override (deployment.Applied): its profile, each part's resources and
  -- the environment the profile changed, and what each part runs on. A
  -- rebuild reapplies it; '{}' is a generation from before it was kept.
  applied JSONB NOT NULL DEFAULT '{}'::jsonb,
  ingress_json JSONB
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_deployment_inputs_release ON deployment_attempt_inputs(release_id) WHERE release_id IS NOT NULL;
-- One need of one project fulfilled in one deployment (§2.5).
CREATE TABLE IF NOT EXISTS need_instances (
  id UUID PRIMARY KEY,
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,
  need             TEXT NOT NULL,
  mode             TEXT NOT NULL DEFAULT 'managed',  -- emulator | managed | register
  binding_json     JSONB NOT NULL DEFAULT '{}'::jsonb,
  secret_refs_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  handle_json      JSONB NOT NULL DEFAULT '{}'::jsonb,
  status           TEXT NOT NULL,  -- creating | ready | failed | orphaned
  updated_at       TIMESTAMPTZ NOT NULL,
  UNIQUE(deployment_id, need)
);
-- What AppTown created for a deployment at its target, recorded when the
-- provider confirmed the creation (design/subsystems/deployment.md).
-- Take-down deletes exactly these; nothing found, reused or adopted is
-- listed. note is '' for a creation AppTown saw; an entry an earlier
-- release's one-time inspection recorded says who approved it.
CREATE TABLE IF NOT EXISTS deployment_owned (
  id UUID PRIMARY KEY,
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL,
  ident         TEXT NOT NULL,
  name          TEXT NOT NULL DEFAULT '',
  holds_data    BOOLEAN NOT NULL DEFAULT false,
  need          TEXT NOT NULL DEFAULT '',
  recorded_at   TIMESTAMPTZ NOT NULL,
  note          TEXT NOT NULL DEFAULT '',
  UNIQUE(deployment_id, kind, ident)
);
-- An image repository AppTown created for a project on a provider's
-- account (its connector): App Platform's DOCR repository, named after the
-- project. AppTown uses only one it recorded creating, and empties it
-- when the project's last deployment on that account is taken down. note
-- says who approved an entry an earlier release's one-time inspection
-- recorded.
CREATE TABLE IF NOT EXISTS owned_repositories (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  connector   TEXT NOT NULL,
  registry    TEXT NOT NULL,
  repository  TEXT NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL,
  note        TEXT NOT NULL DEFAULT '',
  connection_id UUID REFERENCES integrations(id) ON DELETE RESTRICT,
  UNIQUE(connector, registry, repository)
);
-- An offer (§15.7): this target is available to this group, or to
-- everyone ('*'), within these caps. Built-in targets have no rows; they
-- are offered to everyone by construction.
CREATE TABLE IF NOT EXISTS target_offers (
  id UUID PRIMARY KEY,
  target_id UUID NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
  group_name TEXT NOT NULL,
  caps_json  JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT '',
  -- The offerer's principal and way of acting (access.Actor); NULL when not resolved to a person.
  created_by_principal UUID,
  created_by_via TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE(target_id, group_name)
);
-- A data-bearing resource AppTown made for a deployment and kept when
-- the deployment went (§2.6: AppTown never deletes what holds data).
-- Ownership outlives the deployment row: who made it, for what, where.
CREATE TABLE IF NOT EXISTS retained_resources (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL,
  deployment  TEXT NOT NULL,
  target_id UUID,
  need         TEXT NOT NULL,
  handle_json  JSONB NOT NULL DEFAULT '{}'::jsonb,   -- the provider's identity and what was requested
  retained_by  TEXT NOT NULL DEFAULT '',
  -- The retainer's principal and way of acting (access.Actor); NULL for AppTown, or one not resolved to a person.
  retained_by_principal UUID,
  retained_by_via TEXT NOT NULL DEFAULT '',
  retained_at  TIMESTAMPTZ NOT NULL,
  disposition  TEXT NOT NULL DEFAULT 'retained',    -- retained | released | kept
  note         TEXT NOT NULL DEFAULT '',
  settled_by   TEXT NOT NULL DEFAULT '',
  -- The settler's principal and way of acting (access.Actor); NULL unless settled by a resolved person.
  settled_by_principal UUID,
  settled_by_via TEXT NOT NULL DEFAULT '',
  settled_at   TIMESTAMPTZ,
  holds_data   BOOLEAN NOT NULL DEFAULT false            -- data, which blocks the deployment's name until released
);

-- Accepted deployment placement and one preparation claim. The release owns
-- bundle/revision/actor; the queue owns scheduling, not this immutable selection.
CREATE TABLE IF NOT EXISTS release_requests (
  release_id UUID PRIMARY KEY REFERENCES releases(id) ON DELETE CASCADE,
  target_id UUID NOT NULL,
  base_generation BIGINT NOT NULL,
  attributes_json JSONB NOT NULL,
  claimed_at TIMESTAMPTZ,
  -- The copy the release's caller was authorised to fill a new deployment
  -- from (0: none); the release fills that copy or nothing.
  start_from_backup UUID,
  provider_binding_json JSONB,
  ingress_json JSONB,
  authority_json JSONB,
  require_promotion BOOLEAN NOT NULL DEFAULT false
);
-- An operator's override of one part's resources on one deployment
-- (design/subsystems/deployment.md): set as a recorded act,
-- applied over the deployment's profile at each deploy until cleared by
-- an act or by a deploy whose committed profile declares the same values.
CREATE TABLE IF NOT EXISTS deployment_overrides (
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,
  part TEXT NOT NULL,
  memory_bytes BIGINT NOT NULL DEFAULT 0,       -- 0: the override leaves memory as the profile says
  cpus DOUBLE PRECISION NOT NULL DEFAULT 0,      -- 0: the override leaves cpu as the profile says
  reason TEXT NOT NULL,
  set_by TEXT NOT NULL DEFAULT '',
  -- The setter's principal and way of acting (access.Actor); NULL when not resolved to a person.
  set_by_principal UUID,
  set_by_via TEXT NOT NULL DEFAULT '',
  set_at TIMESTAMPTZ NOT NULL,
  memory_unlimited BOOLEAN NOT NULL DEFAULT false, -- explicit operator no-limit choice
  PRIMARY KEY(deployment_id, part)
);

-- What a standing deployment's containers did, as its Docker daemon
-- reported it (docker events): killed out of memory, or exited without
-- anyone stopping them. Observations, not acts (a crash-loop hold is the
-- AppTown's act, with its receipt); read back per deployment and part, kept 30 days. One row per
-- container, kind and moment, so reading a window again records nothing
-- twice.
CREATE TABLE IF NOT EXISTS deployment_limit_events (
  id UUID PRIMARY KEY,
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,
  part TEXT NOT NULL,                       -- the part or need, by name
  kind TEXT NOT NULL CONSTRAINT deployment_limit_event_kind CHECK(kind IN ('out-of-memory','exited')),
  container TEXT NOT NULL,
  at TIMESTAMPTZ NOT NULL,                  -- the daemon's time for it
  exit_code INTEGER,                        -- an exit's code; NULL otherwise
  generation BIGINT,                        -- the generation it happened under; NULL when not known
  UNIQUE(deployment_id, container, kind, at)
);
CREATE INDEX IF NOT EXISTS deployment_limit_events_at ON deployment_limit_events(deployment_id, at);

CREATE TABLE IF NOT EXISTS deployment_storage_bindings (
  id UUID PRIMARY KEY,
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,
  need TEXT NOT NULL CHECK (need <> ''),
  volume TEXT NOT NULL CHECK (volume <> ''),
  data_path TEXT NOT NULL CHECK (data_path <> ''),
  declared_image TEXT NOT NULL CHECK (declared_image <> ''),
  image_id TEXT NOT NULL CHECK (image_id <> ''),
  repo_digest TEXT NOT NULL DEFAULT '',
  volume_created TEXT NOT NULL CHECK (volume_created <> ''),
  volume_driver TEXT NOT NULL CHECK (volume_driver <> ''),
  origin TEXT NOT NULL CHECK (origin IN ('created', 'observed', 'restored')),
  recorded_at TIMESTAMPTZ NOT NULL,
  UNIQUE (deployment_id, need, volume)
);

CREATE TABLE IF NOT EXISTS project_release_settings (
  project_id UUID PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  default_deployment_id UUID,
  revision BIGINT NOT NULL DEFAULT 1 CHECK (revision > 0),
  CONSTRAINT project_release_default_membership FOREIGN KEY(project_id, default_deployment_id)
    REFERENCES deployments(project_id, id) DEFERRABLE INITIALLY DEFERRED
);

-- Desired ingress and retained exact-host memberships belong to Deployment.
-- A single claimant owns a host; multiple claimants retain a legacy conflict.
CREATE TABLE IF NOT EXISTS deployment_address_settings (
  deployment_id UUID PRIMARY KEY REFERENCES deployments(id) ON DELETE CASCADE,
  generated_hostname TEXT NOT NULL DEFAULT '',
  custom_hostname TEXT NOT NULL DEFAULT '',
  certificate_domain TEXT NOT NULL DEFAULT '',
  revision BIGINT NOT NULL DEFAULT 1 CHECK (revision > 0),
  CONSTRAINT deployment_address_ready_fields CHECK (generated_hostname<>'' AND certificate_domain<>'')
);
CREATE TABLE IF NOT EXISTS deployment_hostname_claims (
  hostname TEXT PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS deployment_hostname_claimants (
  hostname TEXT NOT NULL REFERENCES deployment_hostname_claims(hostname) ON DELETE CASCADE,
  deployment_id UUID NOT NULL REFERENCES deployments(id) ON DELETE RESTRICT,
  PRIMARY KEY(hostname,deployment_id)
);

CREATE TABLE deployment_readings (
    id UUID PRIMARY KEY,
    subject TEXT NOT NULL,
    kind TEXT NOT NULL,
    identity TEXT NOT NULL,
    generation BIGINT NOT NULL DEFAULT 0,
    invalidated BOOLEAN NOT NULL DEFAULT FALSE,
    payload JSONB NOT NULL DEFAULT '{}',
    UNIQUE (subject, kind)
);

-- Source: internal/apptown/preview/schema.sql
-- What AppTown created for a preview, by the preview's name: today the
-- AI models key a preview of an app needing llm gets
-- (design/subsystems/integration-runtime.md). It goes when AppTown
-- keeps no record of the preview any more. No reference to the project: a
-- deleted project's preview keys are still revoked.
CREATE TABLE IF NOT EXISTS preview_owned (
  id UUID PRIMARY KEY,
  preview     TEXT NOT NULL,
  project_id UUID NOT NULL,
  kind        TEXT NOT NULL,
  ident       TEXT NOT NULL,
  name        TEXT NOT NULL DEFAULT '',
  recorded_at TIMESTAMPTZ NOT NULL,
  UNIQUE(preview, kind, ident)
);

-- When anyone last looked at a preview, by the preview's name: a request
-- to its address through AppTown, or a boot of it. A preview stops eight
-- hours after its last look; a change's preview keeps its build images and
-- snapshot for thirty days after it, and the look goes with them
-- (design/subsystems/container-lifecycle.md). Written on AppTown's
-- clock, never the database's.
CREATE TABLE IF NOT EXISTS preview_views (
  preview   TEXT PRIMARY KEY,
  viewed_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE preview_readings (
 id UUID PRIMARY KEY,
 subject TEXT NOT NULL UNIQUE,
 identity TEXT NOT NULL,
 payload JSONB NOT NULL
);

-- Source: internal/apptown/dataprotection/schema.sql
-- A set of copies of a deployment's data: where its files are (AppTown's
-- disk or the backup store), what each item is and its digest, and the
-- data class it was taken from. It outlives the deployment it was taken of
-- and is kept with its project until the project is purged.
CREATE TABLE IF NOT EXISTS backups (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL,
  deployment  TEXT NOT NULL,
  taken_at     TIMESTAMPTZ NOT NULL,
  trigger      TEXT NOT NULL DEFAULT 'manual',        -- manual | scheduled | release
  actor        TEXT NOT NULL DEFAULT '',
  -- The taker's principal and way of acting (access.Actor); NULL for AppTown, or one not resolved to a person.
  actor_principal UUID,
  actor_via TEXT NOT NULL DEFAULT '',
  path         TEXT NOT NULL DEFAULT '',              -- the set's directory under <data>/backups
  bytes        BIGINT NOT NULL DEFAULT 0,
  items_json   JSONB NOT NULL DEFAULT '[]'::jsonb,    -- what was taken: kind, name, file, bytes, sha256
  status       TEXT NOT NULL DEFAULT 'ok',            -- ok | partial | failed | pruned
  error        TEXT NOT NULL DEFAULT '',
  -- Where the set's files are: apptown-disk (path is a directory on
  -- AppTown's disk) or store (path is the object prefix in the backup store).
  store        TEXT NOT NULL DEFAULT 'apptown-disk',
  -- The data class of the deployment the set was taken of; '' on sets from
  -- before 8 October 2026. A production copy goes only into production.
  data_class   TEXT NOT NULL DEFAULT '',
  -- Where a set in the store was written: it is read and pruned there.
  store_endpoint TEXT NOT NULL DEFAULT '',
  store_bucket   TEXT NOT NULL DEFAULT ''
);
-- The one backup store an administrator attached: a private bucket in an
-- S3-compatible store, reached with the key pair the named secrets hold.
CREATE TABLE IF NOT EXISTS backup_store (
  id              INT PRIMARY KEY CHECK (id = 1),
  endpoint        TEXT NOT NULL,
  region          TEXT NOT NULL,
  bucket          TEXT NOT NULL,
  access_key_from TEXT NOT NULL,
  secret_key_from TEXT NOT NULL,
  attached_by     TEXT NOT NULL,
  -- The attacher's principal and way of acting (access.Actor); NULL when not resolved to a person.
  attached_by_principal UUID,
  attached_by_via TEXT NOT NULL DEFAULT '',
  attached_at     TIMESTAMPTZ NOT NULL,
  checked_at      TIMESTAMPTZ NOT NULL
);
-- A copy filled into a new, empty place and checked there: whether it came
-- back, from which set, on which target, into which place, as whom.
CREATE TABLE IF NOT EXISTS backup_drills (
  id UUID PRIMARY KEY,
  backup_id UUID NOT NULL,
  project_id UUID NOT NULL,
  deployment   TEXT NOT NULL,
  drilled_at   TIMESTAMPTZ NOT NULL,
  passed       BOOLEAN NOT NULL,
  target       TEXT NOT NULL,
  place        TEXT NOT NULL,
  as_user      TEXT NOT NULL,
  detail       TEXT NOT NULL DEFAULT '',
  operation_id UUID,
  deployment_id UUID, -- the deployment drilled, by id; 0: not provably one
  need         TEXT NOT NULL DEFAULT '' -- the item of the set filled and checked
);
-- A restore rehearsal (design/subsystems/deployment.md): a
-- throwaway place started from a copy, the app booted on it, checked and
-- taken down. Its facts are only what is safe to show a project reader:
-- step names, status codes, names of what was withheld; never output.
CREATE TABLE IF NOT EXISTS restore_rehearsals (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL,
  deployment     TEXT NOT NULL,
  operation_id UUID NOT NULL,
  backup_id UUID NOT NULL,
  release_number BIGINT NOT NULL,
  host           TEXT NOT NULL,
  outcome        TEXT NOT NULL,
  failed_step    TEXT NOT NULL DEFAULT '',
  asked_by       TEXT NOT NULL,
  -- The asker's principal and way of acting (access.Actor); NULL for AppTown, or one not resolved to a person.
  asked_by_principal UUID,
  asked_by_via TEXT NOT NULL DEFAULT '',
  facts_json     JSONB NOT NULL DEFAULT '{}'::jsonb,
  rehearsed_at   TIMESTAMPTZ NOT NULL,
  deployment_id UUID -- the deployment rehearsed, by id
);
-- What a rehearsal makes on the rehearsal host, recorded before it is
-- made, and when it was seen removed: the sweep removes what an ended
-- rehearsal still owns (one AppTown stopped in the middle of, or whose
-- take-down left something).
CREATE TABLE IF NOT EXISTS rehearsal_places (
  operation_id UUID PRIMARY KEY,
  project_id UUID NOT NULL,
  place_json   JSONB NOT NULL,
  recorded_at  TIMESTAMPTZ NOT NULL,
  cleared_at   TIMESTAMPTZ
);
-- A restored copy (design/subsystems/deployment.md): a temporary
-- deployment (kind restored-copy) of a production deployment's current
-- release, started from a copy on the source's own target, behind the
-- AppTown's access gate. The row outlives the deployment it made: it is the
-- evidence of the check and of when it was taken down. It
-- holds only safe facts (step names, status codes, names of what was
-- withheld), never output, and the gate secret only as its SHA-256.
-- app_marker is the copy's own random mark, written before anything is
-- made and rendered into its app: an app found by name is deleted only
-- when it carries it (RTB2-01).
CREATE TABLE IF NOT EXISTS restored_copies (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL,
  -- Within its project: names the copy's deployment (copy-<number>), which
  -- is also its app's name on a platform with short names.
  number             BIGINT NOT NULL,
  source             TEXT NOT NULL,
  source_id UUID NOT NULL,
  deployment         TEXT NOT NULL DEFAULT '',
  deployment_id UUID,
  operation_id UUID NOT NULL,
  backup_id UUID NOT NULL,
  release_number     BIGINT NOT NULL DEFAULT 0,
  target             TEXT NOT NULL DEFAULT '',
  gate_url           TEXT NOT NULL DEFAULT '',
  gate_secret_sha256 TEXT NOT NULL DEFAULT '',
  app_marker         TEXT NOT NULL DEFAULT '',
  asked_by           TEXT NOT NULL,
  -- The asker's principal and way of acting (access.Actor); NULL for AppTown, or one not resolved to a person.
  asked_by_principal UUID,
  asked_by_via TEXT NOT NULL DEFAULT '',
  outcome            TEXT NOT NULL DEFAULT '',
  failed_step        TEXT NOT NULL DEFAULT '',
  facts_json         JSONB NOT NULL DEFAULT '{}'::jsonb,
  started_at         TIMESTAMPTZ NOT NULL,
  checked_at         TIMESTAMPTZ,
  ended_at           TIMESTAMPTZ,
  end_detail         TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS restored_copies_source ON restored_copies (source_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS restored_copies_number ON restored_copies (project_id, number);
-- A one-use ticket AppTown issues itself to check a restored copy's gate,
-- kept by its SHA-256 only. check_operation names the copy's own start: the
-- ticket is redeemed (within a minute, once) by that operation while it
-- runs. Rows from before restored copies were only restore tests may name
-- a person and no operation; they are history.
CREATE TABLE IF NOT EXISTS restored_copy_tickets (
  ticket_sha256   TEXT PRIMARY KEY,
  copy_id UUID NOT NULL REFERENCES restored_copies(id) ON DELETE CASCADE,
  person          TEXT NOT NULL,
  -- The holder's principal and way of acting (access.Actor); NULL for AppTown's own gate check, or one not resolved to a person.
  person_principal UUID,
  person_via TEXT NOT NULL DEFAULT '',
  issued_at       TIMESTAMPTZ NOT NULL,
  expires_at      TIMESTAMPTZ NOT NULL,
  redeemed_at     TIMESTAMPTZ,
  check_operation UUID
);
-- A built-in deployment restored with AppTown: its rebuild fills its data
-- from the set the archive holds (none: the backup took no set, and detail
-- says why), before anything of the app starts. waiting until that rebuild
-- ends, then filled or failed (detail says why).
CREATE TABLE IF NOT EXISTS restore_fills (
  deployment_id UUID PRIMARY KEY REFERENCES deployments(id) ON DELETE CASCADE,
  backup_id UUID,
  state TEXT NOT NULL DEFAULT 'waiting' CONSTRAINT restore_fill_state CHECK (state IN ('waiting', 'filled', 'failed')),
  detail TEXT NOT NULL DEFAULT '',
  updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE protection_readings (
    id UUID PRIMARY KEY,
    subject TEXT NOT NULL,
    kind TEXT NOT NULL,
    identity TEXT NOT NULL,
    generation BIGINT NOT NULL DEFAULT 0,
    invalidated BOOLEAN NOT NULL DEFAULT FALSE,
    payload JSONB NOT NULL DEFAULT '{}',
    UNIQUE (subject, kind)
);

-- Source: internal/apptown/scm/schema.sql
-- SCM owns merge operations; absence is idle, never an incomplete operation.
CREATE TABLE IF NOT EXISTS run_merges (
  run_id UUID PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE,
  state TEXT NOT NULL,
  operation TEXT NOT NULL,
  expected TEXT NOT NULL,
  result TEXT NOT NULL DEFAULT '',
  CONSTRAINT run_merge_tuple CHECK (operation<>'' AND expected<>'' AND
    ((state='merging' AND result='') OR (state='merged' AND result<>'')))
);
CREATE INDEX IF NOT EXISTS run_merges_pending ON run_merges(run_id) WHERE state='merging';

-- SCM owns who may move a project's branch. The generation increases at every
-- handover or replaced attempt; a publisher presents the generation it was
-- admitted under. Absence is generation 0 with no holder.
CREATE TABLE IF NOT EXISTS branch_authority (
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  branch TEXT NOT NULL,
  generation BIGINT NOT NULL,
  holder TEXT NOT NULL,
  PRIMARY KEY (project_id, branch),
  CONSTRAINT branch_authority_tuple CHECK (branch<>'' AND generation>0 AND holder<>'')
);

-- A branch publication admitted but not yet settled. Settled publications are
-- deleted; a row is either in flight or unknown after a crash, and blocks the
-- branch's next handover until it is settled.
CREATE TABLE IF NOT EXISTS branch_publications (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  branch TEXT NOT NULL,
  repository TEXT NOT NULL,
  generation BIGINT NOT NULL,
  expected TEXT NOT NULL,
  proposed TEXT NOT NULL,
  state TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT branch_publication_tuple CHECK (branch<>'' AND repository<>'' AND proposed<>'' AND state IN ('pending','unknown'))
);
CREATE UNIQUE INDEX IF NOT EXISTS branch_publications_one ON branch_publications(project_id, branch);

-- Where a project's main stood when AppTown last moved it: the commit read
-- back from the hub under the repository lock, recorded in the transaction
-- that settled the move. It exists and is an ancestor of (or equal to) the
-- hub's main unless main was rewritten outside AppTown. via names the door
-- (landing, init, seed, copy, genesis, integrity-adopt, backfill, upgrade); run_id is
-- the landing run, 0 for other doors. Absence is unknown.
CREATE TABLE IF NOT EXISTS project_main (
  project_id UUID PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  branch TEXT NOT NULL,
  sha TEXT NOT NULL,
  via TEXT NOT NULL,
  run_id UUID,
  recorded_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT project_main_tuple CHECK (branch<>'' AND sha<>'' AND via IN ('landing','init','seed','copy','genesis','integrity-adopt','backfill','upgrade'))
);

-- A repository attachment is verified provider ownership, independent of the
-- project's human-facing address. Unknown creates remain in the intent table.
CREATE TABLE IF NOT EXISTS repository_attachments (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE,
  connection_id UUID NOT NULL REFERENCES integrations(id),
  provider_kind TEXT NOT NULL CHECK (provider_kind='gitlab'),
  provider_base TEXT NOT NULL CHECK (provider_base<>''),
  provider_account BIGINT NOT NULL CHECK (provider_account>0),
  provider_project BIGINT NOT NULL CHECK (provider_project>0),
  clone_url TEXT NOT NULL CHECK (clone_url<>''),
  project_path TEXT NOT NULL CHECK (project_path<>''),
  verified_at TIMESTAMPTZ NOT NULL
);

-- One attachment operation owns the project's remote choice. A persisted
-- pre-effect intent is not proof that a crashed executor never dispatched.
CREATE TABLE IF NOT EXISTS repository_attachment_intents (
  id UUID PRIMARY KEY,
  request_id UUID NOT NULL,
  project_id UUID NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE,
  actor_id UUID NOT NULL,
  parameters JSONB NOT NULL,
  connection_id UUID NOT NULL REFERENCES integrations(id),
  provider_base TEXT NOT NULL CHECK (provider_base<>''),
  provider_account BIGINT NOT NULL CHECK (provider_account>0),
  prior_origin TEXT NOT NULL,
  phase TEXT NOT NULL CHECK (phase IN ('intent','dispatched','identified','attached','unknown')),
  provider_result JSONB,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  CHECK ((phase IN ('identified','attached')) = (provider_result IS NOT NULL))
);

-- The external identity used to open an MR travels with its original artifact,
-- not with whichever path or attachment happens to be current at merge time.
CREATE TABLE IF NOT EXISTS repository_mr_identities (
  artifact_id UUID PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE,
  identity_json JSONB NOT NULL
);

-- Source: internal/apptown/tasks/schema.sql
-- Tasks owns execution attempts: a step attempt's task is recorded before any
-- provider effect, its provider identity before it starts, and its outcome
-- before the step settles. A settled row is kept as the attempt's receipt.
CREATE TABLE IF NOT EXISTS task_attempts (
  operation TEXT PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  run_id UUID NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  step_id UUID NOT NULL REFERENCES steps(id) ON DELETE CASCADE,
  attempt BIGINT NOT NULL,
  backend TEXT NOT NULL,
  container TEXT NOT NULL,
  digest TEXT NOT NULL,
  -- source is the commit a remote task was given; empty for a task that
  -- mounts AppTown's workspace.
  source TEXT NOT NULL DEFAULT '',
  -- admission is the task's admission as admitted (profile, limits, network,
  -- expiry, as JSON); deadline is when its wall-clock budget ends. A
  -- recovered task keeps both.
  admission TEXT NOT NULL DEFAULT '',
  deadline TIMESTAMPTZ,
  -- invocation names one run of a program within the step attempt: a
  -- script's attempt has one, 'script'; an agent's attempt may have several
  -- in one workspace. workspace names the backend workspace the task shares
  -- with the attempt's other invocations; empty when the task owns its own.
  invocation TEXT NOT NULL DEFAULT 'script',
  workspace TEXT NOT NULL DEFAULT '',
  provider_id TEXT NOT NULL DEFAULT '',
  desired TEXT NOT NULL DEFAULT 'run',
  observed TEXT NOT NULL DEFAULT 'reserved',
  exit_code INT,
  -- timed_out: the decided outcome is a timeout (its exit code -1). Kept
  -- once recorded, through settlement.
  timed_out BOOLEAN NOT NULL DEFAULT false,
  -- detail explains the last transition to people; nothing decides by it.
  detail TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  -- released_at is when the backend confirmed the settled task released
  -- (or that nothing of it was ever held there). A settled row without it
  -- is released again until the backend confirms.
  released_at TIMESTAMPTZ,
  -- workspace_released_at is when the backend confirmed the shared
  -- workspace released, recorded on every row naming it. A workspace is
  -- released only once each of its tasks is settled and released.
  workspace_released_at TIMESTAMPTZ,
  CONSTRAINT task_attempt_tuple CHECK (operation<>'' AND backend<>'' AND container<>'' AND digest<>'' AND attempt>0 AND invocation<>''
    AND desired IN ('run','stop') AND observed IN ('reserved','started','collecting','settled','unknown','refused','held')
    AND (NOT timed_out OR exit_code IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS task_attempts_step_invocation ON task_attempts(step_id, attempt, invocation);
CREATE INDEX IF NOT EXISTS task_attempts_unsettled ON task_attempts(step_id) WHERE observed <> 'settled';
CREATE INDEX IF NOT EXISTS task_attempts_unreleased ON task_attempts(updated_at) WHERE observed = 'settled' AND released_at IS NULL;
CREATE INDEX IF NOT EXISTS task_attempts_workspace ON task_attempts(workspace) WHERE workspace <> '' AND workspace_released_at IS NULL;

-- Source: internal/apptown/evals/schema.sql
-- Evals: is a model or a pack version better or worse? An eval re-runs
-- finished Changes in throwaway copies of their projects, one arm per
-- setup, and compares the arms.

-- One eval, as its starter started it. The meaning is what the starter
-- was shown and agreed to; the subject is the one thing that varies.
CREATE TABLE IF NOT EXISTS evals (
  id UUID PRIMARY KEY,
  -- How people name it ("eval 9"): its number within AppTown, from
  -- eval_numbers, never reused.
  number BIGINT NOT NULL,
  started_by    TEXT NOT NULL,
  -- The starter's principal and way of acting (access.Actor); NULL when
  -- the starter was not resolved to a person.
  started_by_principal UUID,
  started_by_via TEXT NOT NULL DEFAULT '',
  started_at    TIMESTAMPTZ NOT NULL,
  meaning       TEXT NOT NULL,
  subject_kind  TEXT NOT NULL,
  subject       TEXT NOT NULL,
  budget_micros BIGINT NOT NULL,
  state         TEXT NOT NULL DEFAULT 'running',
  reason        TEXT NOT NULL DEFAULT '',
  -- The incomplete spend observations the starter has said to continue
  -- past: one more holds the eval again.
  incomplete_seen BIGINT NOT NULL DEFAULT 0,
  finished_at   TIMESTAMPTZ,
  deleted_at    TIMESTAMPTZ,
  -- subject_digest names exactly what a pack-version eval tested: its
  -- resolved spec and pins at start.
  subject_digest TEXT NOT NULL DEFAULT ''
);

-- One arm: one Change re-run under one setup in its own copy. models_json
-- is the slot → model the arm runs, read when the eval started: what the
-- AppTown may call for its copy.
CREATE TABLE IF NOT EXISTS eval_arms (
  id UUID PRIMARY KEY,
  eval_id UUID NOT NULL REFERENCES evals(id),
  source_project_id UUID NOT NULL,
  source_change_id UUID NOT NULL,
  arm               TEXT NOT NULL,
  profile           TEXT NOT NULL,
  models_json       JSONB NOT NULL DEFAULT '{}'::jsonb,
  state             TEXT NOT NULL DEFAULT 'queued',
  reason            TEXT NOT NULL DEFAULT '',
  project_id UUID,
  change_id UUID,
  run_id UUID,
  landing_run_id UUID,
  started_at        TIMESTAMPTZ,
  ready_at          TIMESTAMPTZ,
  finished_at       TIMESTAMPTZ,
  score_json        JSONB NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(eval_id, source_change_id, arm)
);

-- The copy record: which eval and arm made a copy (whether a project is a
-- copy at all is Project's purpose). Written with the copy, in its creation
-- transaction, and never edited or deleted, not even with the copy or its
-- eval (project ids are never reused), so complaints and spend stay
-- attributed after both are gone.
CREATE TABLE IF NOT EXISTS eval_copies (
  project_id UUID PRIMARY KEY,
  eval_id UUID NOT NULL,
  arm_id UUID NOT NULL,
  arm        TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS evals_number ON evals(number);
-- The last number given to one of evals: the next is one more, whatever was
-- deleted since, so a number never names a second record.
CREATE TABLE IF NOT EXISTS eval_numbers (
  id   BOOLEAN PRIMARY KEY DEFAULT true CONSTRAINT eval_numbers_one CHECK (id),
  last BIGINT NOT NULL
);

-- Source: internal/apptown/maintenance/schema.sql

CREATE TABLE maintenance_readings (
    id UUID PRIMARY KEY,
    subject TEXT NOT NULL,
    kind TEXT NOT NULL,
    identity TEXT NOT NULL,
    generation BIGINT NOT NULL DEFAULT 0,
    invalidated BOOLEAN NOT NULL DEFAULT FALSE,
    payload JSONB NOT NULL DEFAULT '{}',
    UNIQUE (subject, kind)
);

